const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const payload = data.payload || {};
  const isGovVerified = payload.statusSource === 'government_verified';

  const disclaimer = isGovVerified
    ? 'Verified against official government portal records.'
    : 'Status is self-reported by applicant and does NOT constitute official government confirmation or approval.';

  const enTitle = `Application Drafted: ${payload.schemeName}`;
  const enMsg = `Hello ${payload.farmerName || 'Farmer'}, your application draft for ${payload.schemeName} (Ref: ${payload.referenceNumber || 'Pending'}) is created. Action required: ${payload.actionRequired}. Official portal: ${payload.officialPortalUrl}`;

  const hiTitle = `आवेदन दर्ज: ${payload.schemeName}`;
  const hiMsg = `नमस्ते ${payload.farmerName || 'किसान भाई'}, ${payload.schemeName} (संदर्भ: ${payload.referenceNumber || 'प्रक्रियाधीन'}) के लिए आपका आवेदन तैयार है। आवश्यक कार्यवाही: ${payload.actionRequired}। आधिकारिक पोर्टल: ${payload.officialPortalUrl}`;

  return {
    json: {
      ...data,
      processed: {
        eventType: 'government.application.created',
        priority: 'MEDIUM',
        daysRemaining: null,
        statusSource: payload.statusSource || 'user_reported',
        isGovernmentVerified: isGovVerified,
        statusDisclaimer: disclaimer,
        notifications: {
          en: {
            title: enTitle,
            sms: enMsg,
            whatsapp: `*${enTitle}*\n\n${enMsg}\n\n*Disclaimer:* ${disclaimer}`,
            push: enMsg
          },
          hi: {
            title: hiTitle,
            sms: hiMsg,
            whatsapp: `*${hiTitle}*\n\n${hiMsg}\n\n*सूचना:* ${disclaimer}`,
            push: hiMsg
          }
        }
      }
    }
  };
});

