const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const payload = data.payload || {};
  const deadlineDateStr = payload.deadlineDate || payload.reminderDueDate;
  const now = new Date(data.timestamp || Date.now());

  let daysRemaining = null;
  let priority = 'MEDIUM';

  if (deadlineDateStr) {
    const deadline = new Date(deadlineDateStr);
    const diffMs = deadline.getTime() - now.getTime();
    daysRemaining = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

    // Deadline proximity calculation: <= 7 days triggers CRITICAL priority
    if (daysRemaining <= 7) {
      priority = 'CRITICAL';
    } else if (daysRemaining <= 14) {
      priority = 'HIGH';
    } else {
      priority = 'MEDIUM';
    }
  }

  const urgencyPrefix = priority === 'CRITICAL' ? '🚨 CRITICAL DEADLINE' : '⏰ DEADLINE ALERT';
  const urgencyPrefixHi = priority === 'CRITICAL' ? '🚨 अति महत्वपूर्ण अंतिम तिथि' : '⏰ समय सीमा सूचना';

  const enTitle = `${urgencyPrefix}: ${payload.schemeName} (${daysRemaining} days left)`;
  const enMsg = `URGENT: Only ${daysRemaining} days remaining until deadline (${deadlineDateStr}) for ${payload.schemeName}. Complete your submission at ${payload.officialPortalUrl || 'the official portal'}. Action: ${payload.actionRequired}`;

  const hiTitle = `${urgencyPrefixHi}: ${payload.schemeName} (केवल ${daysRemaining} दिन शेष)`;
  const hiMsg = `महत्वपूर्ण: ${payload.schemeName} की अंतिम तिथि (${deadlineDateStr}) में केवल ${daysRemaining} दिन बाकी हैं। तुरंत पोर्टल पर आवेदन पूरा करें: ${payload.officialPortalUrl || 'आधिकारिक पोर्टल'}। कार्यवाही: ${payload.actionRequired}`;

  const isGovVerified = payload.statusSource === 'government_verified';
  const disclaimer = isGovVerified
    ? 'Verified deadline from official government gazette/portal.'
    : 'Indicative deadline based on published scheme calendar.';

  return {
    json: {
      ...data,
      processed: {
        eventType: 'government.deadline.approaching',
        priority,
        daysRemaining,
        statusSource: payload.statusSource || 'user_reported',
        isGovernmentVerified: isGovVerified,
        statusDisclaimer: disclaimer,
        notifications: {
          en: {
            title: enTitle,
            sms: enMsg,
            whatsapp: `*${enTitle}*\n\n${enMsg}\n\n*Portal Link:* ${payload.officialPortalUrl}`,
            push: enMsg
          },
          hi: {
            title: hiTitle,
            sms: hiMsg,
            whatsapp: `*${hiTitle}*\n\n${hiMsg}\n\n*पोर्टल लिंक:* ${payload.officialPortalUrl}`,
            push: hiMsg
          }
        }
      }
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const payload = data.payload || {};
  const dueDateStr = payload.reminderDueDate || payload.deadlineDate;
  const now = new Date(data.timestamp || Date.now());

  let daysRemaining = null;
  let priority = 'MEDIUM';

  if (dueDateStr) {
    const dueDate = new Date(dueDateStr);
    const diffMs = dueDate.getTime() - now.getTime();
    daysRemaining = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
    if (daysRemaining <= 7) {
      priority = 'CRITICAL';
    } else if (daysRemaining <= 14) {
      priority = 'HIGH';
    }
  }

  const enTitle = `Reminder: ${payload.reminderTitle || payload.schemeName}`;
  const enMsg = `Reminder for ${payload.schemeName}: ${payload.reminderTitle || 'Pending task'}. Due date: ${dueDateStr || 'Soon'}. Action: ${payload.actionRequired}`;

  const hiTitle = `स्मरण पत्र: ${payload.reminderTitle || payload.schemeName}`;
  const hiMsg = `${payload.schemeName} के लिए रिमाइंडर: ${payload.reminderTitle || 'लंबित कार्य'}। नियत तिथि: ${dueDateStr || 'शीघ्र'}। कार्यवाही: ${payload.actionRequired}`;

  return {
    json: {
      ...data,
      processed: {
        eventType: 'government.reminder.triggered',
        priority,
        daysRemaining,
        statusSource: payload.statusSource || 'user_reported',
        isGovernmentVerified: payload.statusSource === 'government_verified',
        statusDisclaimer: 'Action reminder scheduled by farmer / AgriDOST assistant.',
        notifications: {
          en: {
            title: enTitle,
            sms: enMsg,
            whatsapp: `*${enTitle}*\n\n${enMsg}\n\n*Portal:* ${payload.officialPortalUrl}`,
            push: enMsg
          },
          hi: {
            title: hiTitle,
            sms: hiMsg,
            whatsapp: `*${hiTitle}*\n\n${hiMsg}\n\n*पोर्टल:* ${payload.officialPortalUrl}`,
            push: hiMsg
          }
        }
      }
    }
  };
});

const crypto = require('crypto');
const items = $input.all();
const secret = $env.N8N_WEBHOOK_SECRET || 'agridost_hmac_webhook_signing_secret_2026';
const baseAppUrl = ($env.AGRIDOST_APP_URL || $env.NEXT_PUBLIC_APP_URL || 'http://host.docker.internal:3000').replace(/\/$/, '');

return items.map(item => {
  const data = item.json;
  const processed = data.processed || {};
  const payload = (data.body && data.body.payload) || data.payload || {};
  const eventId = (data.body && data.body.eventId) || data.eventId || `evt_${Date.now()}`;
  const eventType = processed.eventType || (data.body && data.body.eventType) || data.eventType || 'government.application.created';
  const timestamp = new Date().toISOString();

  const callbackPayload = {
    eventId,
    workflowId: 'government-assistance',
    status: 'success',
    outputSummary: `Government Scheme ${eventType}: Status is ${processed.statusSource || payload.statusSource || 'user_reported'}`,
    outputData: {
      priority: processed.priority || 'MEDIUM',
      daysRemaining: processed.daysRemaining,
      statusSource: processed.statusSource || payload.statusSource || 'user_reported',
      isGovernmentVerified: Boolean(processed.isGovernmentVerified),
      statusDisclaimer: processed.statusDisclaimer || 'Indicative government assistance event.',
      notifications: processed.notifications || {},
      farmerId: (data.body && data.body.farmerId) || data.farmerId || 'unknown-farmer',
      farmId: (data.body && data.body.farmId) || data.farmId || 'unknown-farm',
      idempotencyKey: (data.body && data.body.idempotencyKey) || data.idempotencyKey || `gov:${Date.now()}`,
      processedAt: timestamp
    },
    completedAt: timestamp
  };

  const rawBody = JSON.stringify(callbackPayload);
  const signature = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');

  const signatureHeader = `t=${timestamp},v1=${signature}`;
  const callbackUrl = (data.body && data.body.callbackUrl) || data.callbackUrl || `${baseAppUrl}/api/n8n/callback`;

  return {
    json: {
      callbackUrl,
      callbackPayload,
      rawBody,
      signatureHeader,
      sigTimestamp: timestamp,
      eventId
    }
  };
});
